"""Emitter for app/src/test_digits.h -- shared by scripts/gen_test_digits.py
and python/export_mnist.py so both produce byte-identical header files."""

import os

GRID = 28
NPIX = GRID * GRID

HEADER_PROLOGUE = """\
/* Generated by scripts/gen_test_digits.py (or python/export_mnist.py)
 * -- do not edit by hand.
 *
 * Embedded test inputs for the ExecuTorch MNIST demo on Pico 2 W.
 * Each entry is a float32 [0..1] bitmap of 28x28 pixels (784 values),
 * matching the input contract of the exported model:
 *     input tensor: shape (1, 1, 28, 28), dtype float32, range [0.0, 1.0]
 *
 * Regenerate with:
 *   python3 scripts/gen_test_digits.py --dataset synthetic
 *   python3 scripts/gen_test_digits.py --dataset mnist
 */

#pragma once

#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

#define TEST_DIGIT_COUNT @@COUNT@@
#define TEST_DIGIT_INPUT_SIZE @@NPIX@@
"""

HEADER_EPILOGUE = """\
#ifdef __cplusplus
}
#endif
"""


def emit(names, digits, out_path, labels=None):
    """Write the header.

    names:  list of label strings, e.g. ["0", "1", "4", "7"]
    digits: list of (name, [784 floats in 0..1]) tuples
    labels: expected class index for each entry -- i.e. the argmax index in
            the model's output vector. For a 4-class synthetic model
            (classes 0/1/4/7) this equals the list position; for a 10-class
            MNIST model it is int(name) (e.g. digit "4" -> 4). Defaults to
            the list position when omitted.
    """
    if len(digits) > 16:
        raise ValueError("main.cpp supports up to 16 embedded test digits")
    if labels is None:
        labels = list(range(len(digits)))
    if len(labels) != len(digits):
        raise ValueError("names/labels/digits length mismatch")
    count = len(digits)
    with open(out_path, "w") as f:
        f.write(
            HEADER_PROLOGUE.replace("@@COUNT@@", str(count)).replace(
                "@@NPIX@@", str(NPIX)
            )
        )

        f.write("\n/* Display name for each embedded digit (class label). */\n")
        f.write("static const char *const test_digit_names[TEST_DIGIT_COUNT] = {\n")
        for name in names:
            f.write('    "%s",\n' % name)
        f.write("};\n")

        f.write("\n/* Expected class index (argmax position in model output). */\n")
        f.write("static const uint8_t test_digit_label[TEST_DIGIT_COUNT] = {\n")
        for i in range(count):
            f.write("    %d, /* %s */\n" % (labels[i], names[i]))
        f.write("};\n")

        f.write("\n/* Pixel data: row-major 28x28, float32 in [0.0, 1.0]. */\n")
        f.write(
            "static const float test_digit_input[TEST_DIGIT_COUNT][%d] = {\n" % NPIX
        )
        for name, pix in digits:
            f.write("    { /* '%s' */\n" % name)
            for r in range(GRID):
                row = pix[r * GRID : (r + 1) * GRID]
                f.write("        " + ", ".join("%.4f" % v for v in row) + ",\n")
            f.write("    },\n")
        f.write("};\n")
        f.write(HEADER_EPILOGUE)

    size = os.path.getsize(out_path)
    print("wrote %s (%d bytes, %d digits)" % (out_path, size, count))


def default_out_path():
    """<repo>/app/src/test_digits.h, resolved from this file's location."""
    here = os.path.dirname(os.path.abspath(__file__))
    return os.path.normpath(os.path.join(here, "..", "app", "src", "test_digits.h"))
